-- Schema foundation only. Connected mode remains disabled until complete RLS policies are added.
create extension if not exists pgcrypto;
create table organizations(id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz not null default now());
create table profiles(id uuid primary key references auth.users(id) on delete cascade, display_name text not null, created_at timestamptz not null default now());
create table organization_memberships(organization_id uuid not null references organizations(id) on delete cascade, user_id uuid not null references profiles(id) on delete cascade, role text not null check(role in ('executive','head','employee')), primary key(organization_id,user_id));
create table offices(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,name text not null,created_at timestamptz not null default now());
create table office_layouts(id uuid primary key default gen_random_uuid(),office_id uuid not null references offices(id) on delete cascade,layout jsonb not null,updated_at timestamptz not null default now());
create table departments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,name text not null,head_id uuid references profiles(id));
create table department_memberships(department_id uuid not null references departments(id) on delete cascade,user_id uuid not null references profiles(id) on delete cascade,primary key(department_id,user_id));
create table projects(id uuid primary key default gen_random_uuid(),department_id uuid not null references departments(id) on delete cascade,name text not null,description text not null default '',owner_id uuid references profiles(id),deadline date,status text not null default 'active',created_at timestamptz not null default now());
create table project_milestones(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,name text not null,due date,done boolean not null default false);
create table tasks(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,title text not null,assignee_id uuid references profiles(id),due date,status text not null default 'todo',created_at timestamptz not null default now());
create table issues(id uuid primary key default gen_random_uuid(),department_id uuid not null references departments(id) on delete cascade,project_id uuid references projects(id) on delete set null,title text not null,description text not null,severity text not null,status text not null default 'open',reporter_id uuid not null references profiles(id),escalated boolean not null default false,resolution text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table issue_updates(id uuid primary key default gen_random_uuid(),issue_id uuid not null references issues(id) on delete cascade,author_id uuid not null references profiles(id),body text not null,created_at timestamptz not null default now());
create table meetings(id uuid primary key default gen_random_uuid(),department_id uuid not null references departments(id) on delete cascade,purpose text not null,starts_at timestamptz not null,created_by uuid not null references profiles(id));
create table meeting_participants(meeting_id uuid not null references meetings(id) on delete cascade,user_id uuid not null references profiles(id),primary key(meeting_id,user_id));
create table management_notes(id uuid primary key default gen_random_uuid(),department_id uuid not null references departments(id) on delete cascade,author_id uuid not null references profiles(id),body text not null,created_at timestamptz not null default now());
create table activity_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,actor_id uuid references profiles(id),event_type text not null,payload jsonb not null default '{}',created_at timestamptz not null default now());
create index on departments(organization_id);create index on projects(department_id);create index on tasks(assignee_id,due);create index on issues(department_id,status,severity);create index on activity_events(organization_id,created_at desc);
-- Deny all API access until policies are designed, implemented, and tested.
alter table organizations enable row level security;alter table profiles enable row level security;alter table organization_memberships enable row level security;alter table offices enable row level security;alter table office_layouts enable row level security;alter table departments enable row level security;alter table department_memberships enable row level security;alter table projects enable row level security;alter table project_milestones enable row level security;alter table tasks enable row level security;alter table issues enable row level security;alter table issue_updates enable row level security;alter table meetings enable row level security;alter table meeting_participants enable row level security;alter table management_notes enable row level security;alter table activity_events enable row level security;
